class ConversationPage extends ConsumerStatefulWidget {
  const ConversationPage({super.key});
  @override
  ConsumerState<ConversationPage> createState() => _ConversationPageState();
}

class _ConversationPageState extends ConsumerState<ConversationPage> with WidgetsBindingObserver {
  @override void initState() { super.initState(); WidgetsBinding.instance.addObserver(this); }
  @override void didChangeAppLifecycleState(AppLifecycleState state) { if (state == AppLifecycleState.inactive || state == AppLifecycleState.paused || state == AppLifecycleState.detached) { unawaited(ref.read(conversationControllerProvider.notifier).cancel()); unawaited(ref.read(conversationControllerProvider.notifier).stopPlayback()); } }
  @override void dispose() { WidgetsBinding.instance.removeObserver(this); super.dispose(); }
  @override Widget build(BuildContext context) { final strings = AppStrings(Localizations.localeOf(context)); final speech = ref.watch(speechCapabilitiesProvider); final languages = ref.watch(languagesProvider); final library = ref.watch(localLibraryProvider); final state = ref.watch(conversationControllerProvider); final controller = ref.read(conversationControllerProvider.notifier); return Scaffold(appBar: AppBar(title: Text(strings.conversation), actions: [IconButton(tooltip: strings.settings, icon: const Icon(Icons.settings_outlined), onPressed: () => context.push('/settings'))]), body: speech.when(loading: () => const Center(child: CircularProgressIndicator()), error: (_, __) => Center(child: Text(strings.voiceCapabilitiesError)), data: (capabilities) => languages.when(loading: () => const Center(child: CircularProgressIndicator()), error: (_, __) => Center(child: Text(strings.languagesError)), data: (items) => _ConversationBody(strings: strings, state: state, controller: controller, capabilities: capabilities, languages: items, localSaving: library.enabled))); }
}

