class _Notice extends StatelessWidget { const _Notice({required this.text}); final String text; @override Widget build(BuildContext context) => Padding(padding: const EdgeInsets.only(bottom: 12), child: Text(text, style: TextStyle(color: Theme.of(context).colorScheme.error, fontWeight: FontWeight.w700))); }

T? _firstOrNull<T>(Iterable<T> values, bool Function(T value) test) { for (final value in values) { if (test(value)) return value; } return null; }
